{% extends "layouts/full-width.twig" %}
{% block head_scripts %}
<meta content="index, follow" name="st:robots">
{#
                                                                                                <!-- Swiftype #}
<meta class="swiftype" content="tour" data-type="string" name="page_type" />
{% for bookable_date in all_dates %}
<meta class="swiftype" data-type="date" name="bookable_date" content="{{bookable_date}}" />
{% endfor %}
{% if all_self_guided_dates %}
{% for bookable_date in all_self_guided_dates %}
<meta class="swiftype" data-type="date" name="bookable_self_guided_date" content="{{bookable_date}}" />
{% endfor %}
{% endif %}
{% if all_guided_dates %}
{% for bookable_date in all_guided_dates %}
<meta class="swiftype" data-type="date" name="bookable_guided_date" content="{{bookable_date}}" />
{% endfor %}
{% endif %}
{% if self_guided_date_min %}
<meta class="swiftype" data-type="date" name="self_guided_date_min" content="{{self_guided_date_min}}" />{% endif %}
{% if self_guided_date_max %}
<meta class="swiftype" data-type="date" name="self_guided_date_max" content="{{self_guided_date_max}}" />{% endif %}
{% if guided_date_min %}
<meta class="swiftype" data-type="date" name="guided_date_min" content="{{guided_date_min}}" />{% endif %}
{% if guided_date_max %}
<meta class="swiftype" data-type="date" name="guided_date_max" content="{{guided_date_max}}" />{% endif %}
{% for tour_type in post._bt_tour_type %}
<meta class="swiftype" name="type" data-type="enum" content="{{tour_type}}" />
{% endfor %}
{% if post._bt_self_guided_price %}
<meta class="swiftype" name="self_guided_prices" data-type="enum" content="{{post._bt_self_guided_price}}" />
<meta class="swiftype" name="self_guided_price" data-type="float" content="{{post._bt_self_guided_price}}" />
<meta class="swiftype" name="price" data-type="float" content="{{post._bt_self_guided_price}}" />
{% endif %}
{% if post._bt_guided_price %}
<meta class="swiftype" name="guided_prices" data-type="enum" content="{{post._bt_guided_price}}" />
<meta class="swiftype" name="guided_price" data-type="float" content="{{post._bt_guided_price}}" />
<meta class="swiftype" name="price" data-type="float" content="{{post._bt_guided_price}}" />
{% endif %}
<meta class="swiftype" name="level" data-type="integer" content="{{post._bt_difficulty}}" />
<meta class="swiftype" name="duration" data-type="integer" content="{{post._bt_duration_min}}" />
<meta class="swiftype" name="distance" data-type="float" content="{{post._bt_distance}}" />
<meta class="swiftype" name="tourbook_id" data-type="string" content="{{post._bt_tourbook_id}}" />
<meta class="swiftype" name="tour_code" data-type="string" content="{{post._bt_tour_code}}" />
<meta class="swiftype" name="tour_currency" data-type="string" content="{{post._bt_currency}}" />
{% if post._bt_dates_guided %}
<meta class="swiftype" name="guided_dates" data-type="string" content="{{post._bt_dates_guided}}" />{% endif %}
{% if post._bt_dates_self_guided %}
<meta class="swiftype" name="self_guided_dates" data-type="string" content="{{post._bt_dates_self_guided}}" />
{% endif %}
{% for tour_tag in tour_tags %}
<meta class="swiftype" name="tags" data-type="string" content="{{tour_tag.name}}" />
{% endfor %}
{% for tour_interest in tour_interests %}
<meta class="swiftype" name="tags" data-type="string" content="{{tour_interest.name}}" />
{% endfor %}
{% for country_tag in country_tags %}
{% if country_tag.parent %}
<meta class="swiftype" name="countries" data-type="string" content="{{country_tag.name}}" />
<meta class="swiftype" name="country_slug" data-type="string" content="{{country_tag.slug}}" />
{% endif %}
{% endfor %}
{% for region_tag in region_tags %}
<meta class="swiftype" name="regions" data-type="string" content="{{region_tag.name}}" />
{% endfor %}
<meta class="swiftype" name="image" data-type="enum" content="{{post.thumbnail.src|resize(700,368)}}" />
<meta class="swiftype" name="tourcountry" data-type="string" content="{{canonical_country.name}}" />
<meta class="swiftype" name="tour_operator" data-type="string" content="{{operator.name}}" />
<link rel="canonical" href="{{canonical}}">
{% endblock %}
{% block content %}
<div class="wrapper tour-wrapper content-wrapper">
    <header class="container tour-container tour-header grid">
        {% if post._bt_clickstream %}
        {{ post._bt_clickstream }}
        {% endif %}
        <div class="tour-hero griditem-sm-12 griditem-lg-8 griditem-xlg-9">
            <div class="tour-title-wrap">
                <h2 class="tour-title" data-swiftype-name="title" data-swiftype-type="string">
                    {{post.title}}</h2>
            </div>
            {% if post._bt_images %}
            <div class="tour-slider">
                <div class="slider">
                    {% for img in post._bt_images %}
                    <div class="slide">
                        <img data-lazy="{{img|resize('1080','600','center')}}" src="{{theme.path}}/img/blank.png">
                        {% if post._bt_quote %}
                        <p class="slider__caption">
                            {{ post._bt_quote }}
                        </p>
                        {% endif %}
                    </div>
                    {% endfor %}
                </div>
                {% if post._bt_quote %}
                <span class="slider__caption-mobile">
                    <span>
                        {{ post._bt_quote }}
                    </span>
                </span>
                {% endif %}
            </div>
            {% endif %}
        </div>
        <div class="tour-data griditem-sm-12 griditem-lg-4 griditem-xlg-3 box">
            <div class="tour-data-items">
                <ul>
                    <li>
                        <div data-bv-product-id="{{post._bt_tour_code}}" data-bv-show="rating_summary"></div>
                    </li>
                    <li>
                        <p>
                            <a class="button button-tertiary"
                                href="https://display.ugc.bazaarvoice.com/static/biketoursdirect/main_site/en_US/container.htm?bvaction=rr_submit_review&bvproductId={{post._bt_tour_code}}"
                                id="review-tour-button">Write a Review</a>
                        </p>
                    </li>
                    <li>
                        <span class="tour-data-value">
                            {{post._bt_duration_min}}
                            nights |
                            {{post._bt_distance}}
                            miles/day</span>
                    </li>
                    <li>
                        <span class="tour-data-label">Difficulty Level:
                        </span>
                        <span class="tour-data-value">
                            {{post._bt_difficulty}}
                            <a class="info-tooltip" data-lity href="#tooltip-levels"></a>
                        </span>
                    </li>
                    {% if post._bt_guided_price %}
                    {% if post._bt_currency == 'EUR' %}
                    {% if inEU == 'false' and client_country == 'US' %}
                    <li>
                        <span class="tour-data-label">Guided from:</span>
                        <span class="tour-data-value">
                            US${{ (post._bt_guided_price*(rates.USD.1 + buy_rate_value))|round }}</span>
                    </li>
                    {% endif %}
                    {% if inEU == 'false' and client_country == 'CA' %}
                    <li>
                        <span class="tour-data-label">Guided from:</span>
                        <span class="tour-data-value">
                            CAN${{ (post._bt_guided_price*(rates.CAD.1 + buy_rate_value))|round }}</span>
                    </li>
                    {% endif %}
                    {% if inEU == 'true' %}
                    <li>
                        <span class="tour-data-label">Guided from:</span>
                        <span class="tour-data-value">
                            &euro;{{ post._bt_guided_price }}</span>
                    </li>
                    {% endif %}
                    {% if inEU == 'false' and client_country != 'US' and client_country != 'CA' %}
                    <li>
                        <span class="tour-data-label">Guided from:</span>
                        <span class="tour-data-value">
                            {{post._bt_currency|replace({'EUR': '&euro;'})}}{{ post._bt_guided_price }}</span>
                    </li>
                    {% endif %}
                    {% if not inEU and not client_country %}
                    <li>
                        <span class="tour-data-label">Guided from:</span>
                        <span class="tour-data-value">
                            {{post._bt_currency|replace({'EUR': '&euro;'})}}{{ post._bt_guided_price }}</span>
                    </li>
                    {% endif %}
                    {% elseif post._bt_currency == 'USD'%}
                    <span class="tour-data-label">Guided from:</span>
                    <span class="tour-data-value">
                        {% for currency,rate in convert_rates %}
                        {% if post._bt_currency == currency %}
                        {% set usPrice = (post._bt_guided_price*rate)|round %}
                        {% if client_country == 'US' and inEU == 'false' %}
                        US${{ post._bt_guided_price }}
                        {% elseif client_country == 'CA' and inEU == 'false' %}
                        CAN${{ (post._bt_guided_price/convert_rates.CAD)|round }}
                        {% elseif client_country != 'US' and client_country != 'CA' and inEU == 'true' %}
                        &euro;{{ (post._bt_guided_price/convert_rates.EUR)|round }}
                        {% else %}
                        {{bt._tour_currency}}
                        {{bt.bt_guided_price}}
                        {% endif %}
                        {% endif %}
                        {% endfor %}
                    </span>
                    {% else %}
                    {% for currency,rate in convert_rates %}
                    {% if post._bt_currency == currency %}
                    <strong>Guided:
                    </strong>from
                    <strong>
                        {% set usPrice = (post._bt_guided_price*rate)|round %}
                        {% if client_country == 'US' and inEU == 'false'%}
                        US${{ usPrice }}
                        {% elseif client_country == 'CA' and inEU == 'false'%}
                        CAN${{ (usPrice/(convert_rates.CAD - buy_rate_value))|round }}
                        {% elseif client_country != 'US' and client_country != 'CA' and inEU == 'true'%}
                        &euro;{{ (usPrice/(convert_rates.EUR - buy_rate_value))|round }}
                        {% else %}
                        {{post._bt_currency}}
                        {{post._bt_guided_price}}
                        {% endif %}
                    </strong>
                    {% endif %}
                    {% endfor %}
                    {% endif %}
                    {% endif %}
                    {% if post._bt_self_guided_price and post._bt_guided_price %}
                    <br>
                    {% endif %}
                    {% if post._bt_self_guided_price %}
                    {# {{post._bt_self_guided_price}} #}
                    {# {{rates.USD.1}} #}
                    {# {{buy_rate_value}} #}
                    {% if post._bt_currency == 'EUR' %}
                    {% if inEU == 'false' and client_country == 'US' %}
                    <li>
                        <span class="tour-data-label">Self-guided from:</span>
                        <span class="tour-data-value">
                            US${{ (post._bt_self_guided_price*(rates.USD.1 + buy_rate_value))|round }}</span>
                    </li>
                    {% endif %}
                    {% if inEU == 'false' and client_country == 'CA' %}
                    <li>
                        <span class="tour-data-label">Self-guided from:</span>
                        <span class="tour-data-value">
                            CAN${{ (post._bt_self_guided_price*(rates.CAD.1 + buy_rate_value))|round }}</span>
                    </li>
                    {% endif %}
                    {% if inEU == 'true' %}
                    <li>
                        <span class="tour-data-label">Self-guided from:</span>
                        <span class="tour-data-value">
                            &euro;{{ post._bt_self_guided_price }}</span>
                    </li>
                    {% endif %}
                    {% if inEU == 'false' and client_country != 'US' and client_country != 'CA' %}
                    <li>
                        <span class="tour-data-label">Self-guided from:</span>
                        <span class="tour-data-value">
                            {{post._bt_currency|replace({'EUR': '&euro;'})}}{{ post._bt_self_guided_price }}</span>
                    </li>
                    {% endif %}
                    {% if not inEU and not client_country %}
                    <li>
                        <span class="tour-data-label">Self-guided from:</span>
                        <span class="tour-data-value">
                            {{post._bt_currency|replace({'EUR': '&euro;'})}}{{ post._bt_self_guided_price }}</span>
                    </li>
                    {% endif %}
                    {% elseif post._bt_currency == 'USD'%}
                    <span class="tour-data-label">Self-guided from:</span>
                    <span class="tour-data-value">
                        {% for currency,rate in convert_rates %}
                        {% if post._bt_currency == currency %}
                        {% set usPrice = (post._bt_self_guided_price*rate)|round %}
                        {% if client_country == 'US' and inEU == 'false'%}
                        US${{ post._bt_self_guided_price }}
                        {% elseif client_country == 'CA' and inEU == 'false'%}
                        CAN${{ (post._bt_self_guided_price/convert_rates.CAD)|round }}
                        {% elseif client_country != 'US' and client_country != 'CA' and inEU == 'true'%}
                        &euro;{{ (post._bt_self_guided_price/convert_rates.EUR)|round }}
                        {% else %}
                        {{bt._tour_currency}}
                        {{bt._self_guided_price}}
                        {% endif %}
                        {% endif %}
                        {% endfor %}
                    </span>
                    {% else %}
                    {% for currency,rate in convert_rates %}
                    {% if post._bt_currency == currency %}
                    <strong>Self-guided:
                    </strong>from
                    <strong>
                        {% set usPrice = post._bt_self_guided_price*rate %}
                        {% if client_country == 'US' and inEU == 'false'%}
                        US${{ usPrice|round }}
                        {% elseif client_country == 'CA' and inEU == 'false'%}
                        CAN${{ (usPrice/(convert_rates.CAD - buy_rate_value))|round }}
                        {% elseif client_country != 'US' and client_country != 'CA' and inEU == 'true'%}
                        &euro;{{ (usPrice/(convert_rates.EUR - buy_rate_value))|round }}
                        {% else %}
                        {{post._bt_currency}}
                        {{post._bt_self_guided_price}}
                        {% endif %}
                    </strong>
                    {% endif %}
                    {% endfor %}
                    {% endif %}
                    {% endif %}
                    <li>
                        {% if post._bt_dates_guided or post._bt_dates_self_guided %}
                        <span class="tour-data-label">
                            <a class="scrollto tour-data-label-link" data-offset="150" data-target="#dates_prices-tab"
                                href="#dates_prices">View Dates</a>
                        </span>
                        {% endif %}
                    </li>
                </ul>
            </div>
            <div class="lity-hide" id="tooltip-levels">
                <div class="lity-content-inner">
                    <h3 class="modal-title">Level of difficulty</h3>
                    <p>
                        <strong>Tours using road, hybrid or touring bikes:</strong>
                    </p>
                    <ol>
                        <li>Mostly flat</li>
                        <li>Flat with some gentle slopes</li>
                        <li>Rolling, hilly terrain</li>
                        <li>Some long and/or steep climbs</li>
                        <li>Extensive climbing</li>
                    </ol>
                    <p>
                        <strong>Tours using mountain bikes:</strong>
                    </p>
                    <ol>
                        <li>Mostly flat, wide trails</li>
                        <li>Some gentle slopes, wide trails</li>
                        <li>Rolling, hilly terrain and/or narrow trails</li>
                        <li>Some long and/or steep climbs and/or technical trails</li>
                        <li>Extensive climbing and/or highly technical trails</li>
                    </ol>
                </div>
            </div>
            <div class="tour-cta">
                <p>
                    <a href="{{site.url}}/book-a-tour/{{post.post_name}}" data-sticky-for="1140"
                        data-sticky-class="is_stuck" data-margin-top="62" class="sticky button button-primary"
                        id="book-tour-button">Book my tour now</a>
                </p>
                <p>
                    <a href="{{site.url}}/ask-a-tour-advisor?tourname={{post.title}}" class="button button-tertiary">Ask
                        a Tour Advisor</a>
                </p>
                <p class="tour-data-link">
                    <a data-lity href="#why-book">Why book with us?</a>
                </p>
