<div class="tour-menu-wrapper wrapper sticky" data-margin-top="70" data-sticky-class="is_stuck">
    <div class="tour-menu-container container">
        <ul class="nav nav-tabs tour-tabs" id="tour-tabs" role="tablist">
            {% for key,tab in tabs %}
            {% set current_tab = '_bt_'~key~'_content' %}
