            <li class="nav-item">
                <a class="nav-link" id="{{key}}-tab" data-toggle="tab" data-target="#{{key}}" href="#" role="tab"
                    aria-controls="{{key}}" aria-expanded="true">
                    {{tab.tab_name}}</a>
            </li>
            {% endif %}
            {% endif %}
            {% endfor %}
            <li class="nav-item nav-item-desktop">
                <a aria-controls="reviews" class="nav-link" data-target="#reviews" data-toggle="tab" href="#"
                    id="reviews-tab" role="tab">Reviews</a>
            </li>
            {# <li class="nav-item nav-item-desktop">
                                                                                                                                                                                                                                                                                                                                                				<a class="nav-link" id="hosts-tab" data-toggle="tab" data-target="#hosts" href="#hosts" role="tab" aria-controls="hosts">Local Hosts</a>
                                                                                                                                                                                                                                                                                                                                                			</li>
                                                                                                                                                                                                                                                                                                                                                			 #}
        </ul>
    </div>
</div>
<div class="tour-content-wrapper wrapper">
    <div class="tour-content-container container grid">
        <div class="tour-content griditem-sm-12 griditem-md-12">
            <div class="tour-type-toggle">
                <span>Tour Type:</span>
                {% if packages.guided is defined %}
                <a class="tour-type-button tour-type-active" data-tourtype="guided" href="#">
                    {% else %}
                    <span class="disabled tour-type-button">
                        {% endif %}
                        Guided
                        {% if packages.guided is defined %}
                </a>
                {% else %}
                </span>
                {% endif %}
                {% if (packages.guided is defined) and (packages.self_guided is defined) %}
                <a class="tour-type-button" data-tourtype="self_guided" href="#">
                    {% elseif packages.self_guided is defined %}
                    <a class="tour-type-button tour-type-active" data-tourtype="guided" href="#">
                        {% else %}
                        <span class="disabled tour-type-button">
                            {% endif %}
                            Self-guided
                            {% if packages.self_guided is defined %}
                    </a>
                    {% else %}
                    </span>
                    {% endif %}
            </div>
            <div class="tab-content" id="tab-content" role="tablist">
                {% for key,tab in tabs %}
                {% set current_tab = '_bt_'~key~'_content' %}
                {% if attribute(post, current_tab)|length > 0 or tab.required == 1 %}
                {% if attribute(post, current_tab)[0].title or attribute(post, current_tab)[0].section_content or tab.required == 1 %}
                <div class="tour-tab-toggle-wrap">
                    <a class="tour-tab-toggle" id="{{key}}-toggle" data-toggle="tab" data-target="#{{key}}" href="#"
                        role="tab" aria-expanded="true" aria-controls="{{key}}">
                        {{tab.tab_name}}
                        <span class="icon-wrap icon-wrap-lg icon-wrap-white">
                            {{include('inc/icons/minus.svg')}}
                        </span>
                        <span class="icon-wrap icon-wrap-lg icon-wrap-white icon-wrap-second">
                            {{include('inc/icons/minus.svg')}}
                        </span>
                    </a>
                </div>
                <div class="tour-content-tab tab-pane" id="{{key}}" role="tabpanel" aria-labelledby="{{key}}-tab">
                    <div class="grid" id="{{key}}-section">
                        <div class="tour-content-tab-main griditem-sm-12{% if tab.sidebar %} griditem-lg-7{% endif %}">
                            {% for main in tab.main %}
                            <div
                                class="page-content-body tour-content-inner tour-content-main{% if main.type == 'guided' %} tour-content-toggle tour-is-active{% endif %}{% if main.type == 'self_guided' %} tour-content-toggle tour-is-hidden{% endif %}">
                                <h2 class="tour-content-title tour-content-main-title">
                                    {{main.title}}</h2>
                                <div data-swiftype-name="body" data-swiftype-type="text">
                                    {{ function('wysiwyg_output',main.section_content) }}
                                </div>
                            </div>
                            {% endfor %}
                            {% if key == "dates_prices" %}
                            {% for package_type,all_packages in packages %}
                            {% if packages|length > 1 %}
                            <div
                                class="tour-content-inner tour-content-main package {% if package_type == 'guided' %} tour-content-toggle tour-is-active{% else %} tour-content-toggle tour-is-hidden{% endif %}">
                                {% else %}
                                <div class="tour-content-inner tour-content-main package tour-is-active">
                                    {% endif %}
                                    <div class="package-dates">
                                        <h2 class="package-prices-header">Dates</h2>
                                        {% if package_type == 'guided' %}
                                        {{post._bt_dates_guided}}
                                        {% endif %}
                                        {% if package_type == 'self_guided' %}
                                        {{post._bt_dates_self_guided}}
                                        {% endif %}
                                        {% for package in all_packages %}
                                        {% if loop.index == 1 %}
                                        {% if package._bt_tour_package_seasons|length > 1 %}
                                        <div class="package-prices-seasons">
                                            {% for season in package.seasons %}
                                            <div class="package-prices-season">
                                                <span class="package-prices-season-label">
                                                    {{season.display_name.en}}:</span>
                                                <span class="package-prices-season-value">
                                                    {% for period in season.periods %}
                                                    {{period.from|date('M d, Y')}}
                                                    -
                                                    {{period.to|date('M d, Y')}}{% if not loop.last %},
                                                    {% endif %}
                                                    {% endfor %}
                                                </span>
                                            </div>
                                            {% endfor %}
                                        </div>
                                        {% endif %}
                                        {% endif %}
                                        {% endfor %}
                                    </div>
                                    <div class="package-prices">
                                        <h2 class="package-prices-header">Prices</h2>
                                        <div class="price-switch">
                                            <!-- Local Price -->
                                            <div class="currency_switcher currency-rates" style="display: none">
                                                {# TODO: Replace with ajax called rates #}
                                                <script>
                                                    $(document).ready(function () {
                                                        var rates = {{ rates| json_encode | raw
                                                    }};
                                                    window.rates = rates;
                                                    console.log(rates)
                                                    var corates = {{ convert_rates| json_encode | raw }};
                                                    window.corates = corates;
                                                    console.log(corates)
                                                    var buyrate = {{ buy_rate_value| json_encode | raw }};
                                                    window.buyrate = buyrate;
                                                    console.log(buyrate)
                                                });
                                                </script>
                                            </div>
                                            <div class="local-price">
                                                <span>Local: </span>
                                                <div class="currency-local">
                                                    <button data-currency="{{local_currency}}"
                                                        class="currency-button currency-local">{{local_currency|replace({'EUR': '&euro;', 'USD': '&dollar;', 'CAD': '&dollar;', 'GBP': '&pound;', 'CHF': '&#8355; '})}}
                                                        {{local_currency}}</button>
                                                </div>
                                            </div>
                                            <!-- /Local Price -->
                                            <!-- Others Price -->
                                            <div class="others-price">

                                                <nav class="currency-menu">
                                                    <ul>
                                                        <li>
                                                            <p>Show prices in:</p>
                                                        </li>
                                                        <li>
                                                            <button
                                                                class="currency-button currency-eur others-currency-button"
                                                                data-currency="EUR">&euro; EUR</button>
                                                        </li>
                                                        <li>
                                                            <button
                                                                class="currency-button currency-usd others-currency-button"
                                                                data-currency="USD">&dollar; USD</button>
                                                        </li>
                                                        <li>
                                                            <button
                                                                class="currency-button currency-cad others-currency-button"
                                                                data-currency="CAD">&dollar; CAD</button>
                                                        </li>
                                                    </ul>
                                                </nav>
                                            </div>
                                            <div class="price-switch-right-text">
                                                <p>We price in local currencies to save you money.
                                                    <a href="https://www.biketours.com/exchange-rates/">How?</a>
                                                </p>
                                            </div>
                                        </div>
                                        <!-- /Others Price -->
                                        <!-- Packages -->
                                        {% for package in all_packages %}
                                        <div class="package-prices-group">
                                            <div class="switcher-button-change-text">
                                                <p class="local">Prices are shown in local currency
                                                    {{local_currency}}
                                                    .</p>
                                                <p class="eur">Prices in Euro are based on current exchange rates and
                                                    will vary.</p>
                                                <p class="usd">Prices in United States dollars are based on current
                                                    exchange rates and will vary.</p>
                                                <p class="cad">Prices in Canadian dollars are based on current exchange
                                                    rates and will vary.</p>
                                            </div>
                                            {% for name, base in package.base %}
                                            <div class="package-prices-subgroup">
