                                                        {{post._bt_currency|replace({'EUR': '&euro; ', 'GBP': '&pound; ', 'USD': '&dollar; ', 'CAD': '&dollar; ', 'CHF': '&#8355; '})}}{{base_price.value}}
                                                    </div>
                                                </div>
                                                {% endfor %}
                                                {% if base.base_services %}
                                                {% for key, base_service in base.base_services %}
                                                {% for service_type, service in base_service %}
                                                {% if service|length > 1 %}
                                                <div class="package-prices-price-label">
                                                    {{service_type}}
                                                </div>
                                                {% for key, s in service %}
                                                <div class="package-prices-price package-prices-price-sub">
                                                    <div class="package-prices-price-label">
                                                        {{s.label}}
                                                    </div>
                                                    <div class="package-prices-price-value convert currency-main">
                                                        {{post._bt_currency|replace({'EUR': '&euro; ', 'GBP': '&pound; ', 'USD': '&dollar; ', 'CAD': '&dollar; ', 'CHF': '&#8355; '})}}{{s.value}}
                                                    </div>
                                                </div>
                                                {% endfor %}
                                                {% else %}
                                                <div class="package-prices-price package-prices-price">
                                                    <div class="package-prices-price-label">
                                                        {{service_type}}
                                                    </div>
                                                    <div class="package-prices-price-value convert currency-main">
                                                        {{post._bt_currency|replace({'EUR': '&euro; ', 'GBP': '&pound; ', 'USD': '&dollar; ', 'CAD': '&dollar; ', 'CHF': '&#8355; '})}}{{service.0.value}}
                                                    </div>
                                                </div>
                                                {% endif %}
                                                {% endfor %}
                                                {% endfor %}
                                                {% endif %}
                                                {# Additional Prices #}
                                            </div>
