                                                        {{season.display_name.en}}
                                                        {% endif %}
                                                        {% endfor %}
                                                    </div>
                                                    <div class="package-prices-price-value convert currency-main">
                                                        {{prices.price.currency|replace({'EUR': '&euro; ', 'GBP': '&pound; ', 'USD': '&dollar; ', 'CAD': '&dollar; ', 'CHF': '&#8355; '})}}{{prices.price.value}}
                                                    </div>
                                                </div>
                                                {% endfor %}
                                                {% else %}
                                                <div class="package-prices-price">
                                                    <div class="package-prices-price-label">
                                                        {% if service.display_name.en == "Basic trip" %}
                                                        <strong>Per person, double occupancy</strong>
                                                        {% else %}
                                                        {{service.display_name.en}}
                                                        {% endif %}
                                                    </div>
                                                    <div Basic
                                                        class="package-prices-price-value convert currency-main{% if service.display_name.en == " trip" %} package-prices-price-value-base{% endif %}">
                                                        {% for prices in service.conditions %}
                                                        {{prices.price.currency|replace({'EUR': '&euro; ', 'GBP': '&pound; ', 'USD': '&dollar; ', 'CAD': '&dollar; ', 'CHF': '&#8355; '})}}{{prices.price.value}}
                                                        {% endfor %}
                                                    </div>
                                                </div>
                                                {% endif %}
                                                {% endfor %}
                                            </div>
                                            {% endfor %}
                                            {% if package.discounts and package.discounts.values %}
                                            <div class="package-prices-subgroup">
                                                <h5 class="package-prices-title">
                                                    {{package.discounts.label}}</h5>
                                                {% for discount in package.discounts.values %}
