                                                        {{discount.value|replace({'-': ''})}}%
                                                        {% endif %}
                                                        {% if discount.unit == "pricedifference" %}
                                                        {{post._bt_currency|replace({'EUR': '&euro; ', 'GBP': '&pound; ', 'USD': '&dollar; ', 'CAD': '&dollar; ', 'CHF': '&#8355; '})}}{{discount.value}}
                                                        {% endif %}
                                                    </div>
                                                </div>
                                                {% endfor %}
                                            </div>
                                            {% endif %}
                                        </div>
                                        {% endfor %}
                                    </div>
                                </div>
                                {% endfor %}
                                {% endif %}
