                                <div
                                    class="page-content-body tour-content-inner tour-content-sidebar{% if sidebar.type == 'guided' %} tour-content-toggle tour-is-active{% endif %}{% if sidebar.type == 'self_guided' %} tour-content-toggle tour-is-hidden{% endif %}">
